**Step 9: Provide Proactive Outreach**

Reach out to consumers who haven't started migration:

```python
# Automated outreach script
def identify_at_risk_consumers():
    """Identify consumers who need proactive support"""

    at_risk = []
    days_until_sunset = 90

    for consumer in all_consumers:
        # Check if consumer has started migration
        replacement_api_usage = get_api_usage(
            consumer.id,
            endpoint="/api/v2/claims/submit",
            days=30
        )

        deprecated_api_usage = get_api_usage(
            consumer.id,
            endpoint="/api/v1/claims/submit",
            days=30
        )

        # Consumer still using deprecated API exclusively
        if deprecated_api_usage > 0 and replacement_api_usage == 0:
            # High volume consumers are higher risk
            risk_level = "CRITICAL" if deprecated_api_usage > 10000 else "HIGH"

            at_risk.append({
                "consumer": consumer,
                "risk_level": risk_level,
                "monthly_requests": deprecated_api_usage,
                "days_until_sunset": days_until_sunset,
                "recommended_action": "Schedule migration consultation call"
            })

    return at_risk

# Send personalized outreach
for consumer_risk in identify_at_risk_consumers():
    if consumer_risk["risk_level"] == "CRITICAL":
        # Escalate to account management
        notify_account_team(consumer_risk)
    else:
        # Send automated reminder with migration resources
        send_migration_reminder(consumer_risk["consumer"])
```

**Step 10: Update Deprecation Warnings**

As sunset date approaches, increase warning severity:

```javascript
// Progressive warning intensity
function getDeprecationWarning(daysUntilSunset) {
  if (daysUntilSunset <= 30) {
    return {
      severity: 'CRITICAL',
      header: 'X-API-Warn',
      message: `URGENT: This API will be disabled in ${daysUntilSunset} days. ` +
               `Immediate migration required to avoid service disruption.`
    };
  } else if (daysUntilSunset <= 60) {
    return {
      severity: 'HIGH',
      header: 'X-API-Warn',
      message: `WARNING: This API will be disabled in ${daysUntilSunset} days. ` +
               `Please complete migration soon.`
    };
  } else {
    return {
      severity: 'MEDIUM',
      header: 'X-API-Warn',
      message: `This API is deprecated and will be disabled on ${sunsetDate}. ` +
               `Please plan migration.`
    };
  }
}
```
